# Public API (cmgr:*)
  @api cmgr:register(name, fn, undoDesc)  @ 126
      @contract  delegates to the global scope — root-level commands are gated-to-global, which is always reachable; the duplicated registration body now lives only in scope:register  @ 125
  @api cmgr:registerAll(tbl)  @ 127
  @api cmgr:rootKeymap()  @ 130
      @contract  returns the bottom-of-stack ('global') keymap directly — used by dispatchers that want to fire ONLY root bindings (e.g. trackerPage's swing editor wants playPause/quit live but page-scoped commands off)  @ 129
  @api cmgr:bind(name, keys)  @ 132
  @api cmgr:bindAll(tbl)  @ 133
  @api cmgr:installManifest(manifest, ImGui)  @ 145-170
      @contract  parses each entry's tokens into its scope's keymap and hangs scope.manifest  @ 144
  @api cmgr:entry(name)  @ 173-177
      @contract  raises on a name no manifest declares, so a consumer naming a stale command fails loudly  @ 172
  @api cmgr:auditManifests()  @ 181-204
      @contract  a declared scope's entries and its registrations must correspond, both ways  @ 179
      @contract  a scope that registers a command while declaring no manifest raises  @ 180
  @api cmgr:wrap(name, wrapper)  @ 207-211
      @contract  wrap is a no-op if name has no registered command; wrappers stack (compose outward)  @ 206
  @api cmgr:doBefore(name, before)  @ 216-224
      @contract  doBefore/doAfter accept either a single name or an array of names  @ 213
      @contract  doAfter preserves the original command's return values (the dispatch signal)  @ 214
      @invariant  wraps compose inside the gate — when invoke skips a gated command, no doBefore / doAfter side-effect fires  @ 215
  @api cmgr:doAfter(name, after)  @ 226-236
  @api cmgr:beginPrefix()  @ 258
      @contract  buffer accepts only '0'..'9' and '/'; cancel/finish/invoke each leave the state inactive  @ 257
  @api cmgr:isPrefixActive()  @ 259
  @api cmgr:appendPrefix(ch)  @ 261-265
  @api cmgr:cancelPrefix()  @ 267
  @api cmgr:finishPrefix()  @ 270-288
      @contract  empty buffer or unparseable input → nil pending value; '/' with empty numerator or denominator parses as nil; integer N stored as (N/1)  @ 269
  @api cmgr:prefixRational()  @ 291-293
      @contract  non-consuming reader of the parsed rational; safe to call inside a command body. Returns (nil, nil) when no prefix is pending. State is cleared at the end of invoke, not by this call.  @ 290
  @api cmgr:scope(name)  @ 298-305
      @contract  creates the scope on first request; idempotent thereafter  @ 297
  @api cmgr:push(s)  @ 310-314
      @contract  push(name|scope); creates a named scope if absent. Top-of-stack is the most recently pushed.  @ 309
  @api cmgr:pop(s)  @ 317-321
      @contract  pop(name|scope) asserts the named scope is currently on top; pops it  @ 316
  @api cmgr:lastCommand()  @ 329
      @contract  name and serial of the last body run; unknown or gated-out changes neither  @ 328
  @api cmgr:invoke(name, ...)  @ 334-354
      @contract  returns nil when the command is unknown OR registered on a scope that is not currently reachable (off-stack or blocked by a modal above)  @ 331
      @contract  always prepends the pending prefix (defaulted to 1 when nothing is pending) as the first argument to the command body. Bodies that need to distinguish "user typed 1" from "no prefix" read prefixRational() — it returns (nil, nil) when nothing is pending. State stays live for the call so the body may read it; cleared on return ONLY if there was a pending prefix at entry, so a command body that opens prefix mode (beginPrefix) is not wiped out by its own invoke.  @ 332
      @contract  spring-loaded scope: redirect[] runs fn in-place; keepAlive[] passes; else onBail()  @ 333
  @api cmgr:keysFor(name)  @ 370
  @api cmgr:keychain()  @ 373-390
      @contract  returns one keymap per stack scope in top-down order; modal scopes filter lower keymaps to their passthrough name set, then halt the walk  @ 372
  @api cmgr:keySpec(spec, ImGui)  @ 393-398
      -- ImGui injected so cmgr stays free of REAPER-side imports at module load.
  @api cmgr:commandAtKey(spec, exceptName, ImGui)  @ 404-416
      @contract  reachable command for spec's key (keychain top-down); skips exceptName; nil if free  @ 403
  @api cmgr:bindingSite(name)  @ 419-426
      @contract  scope to edit name's binding in: scope currently binding it, else its gate scope  @ 418
  @api cmgr:noteChars(char)  @ 432-434
      -- Re-read noteLayout on each call so a config change takes effect
      -- without rebuilding vm.
  @api cmgr:keyLabel(spec, ImGui)  @ 521-533
  @api cmgr:keyLabelList(name, ImGui)  @ 536-542
      @contract  list of human labels, one per bound keyspec of the reachable command, or nil if unbound  @ 535
  @api cmgr:keyLabels(name, ImGui)  @ 545-548
      @contract  keyLabelList joined by ' / ', or nil if unbound on the current stack  @ 544
  @api cmgr:tokenForSpec(spec, ImGui)  @ 610-621
      @contract  spec -> stable ASCII token ("Ctrl+Z"); nil if the key has no token name  @ 609
  @api cmgr:specForToken(token, ImGui)  @ 624-639
      @contract  token -> keyspec (bare key | {key, mod...}); (nil, err) on an unknown key/modifier  @ 623
  -- Binding overrides (persisted, hand-editable)
  @api cmgr:loadOverrides(ImGui)  @ 645-660
      @contract  a malformed token is warned and skipped; the command keeps its other (good) bindings  @ 644
  @api cmgr:rebind(scopeName, name, specs, ImGui)  @ 663-673
      @contract  overwrites the scope's binding for name and persists it as tokens (global tier)  @ 662

